#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 15a: the language layer
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check it, then fast forward main.
#
# After this part (plan: claude/language-plan.md):
#   * five interface languages: English (default), Spanish, French, Arabic
#     and Portuguese, with next-intl 4.14.9; addresses stay the same
#   * the language comes from the one language cookie (set only when
#     someone picks a language), else the browser's language, else English
#   * a language picker in the sidebar and in Settings; a signed in wallet
#     keeps its choice on the server (user_settings.language), so it
#     follows the wallet to other devices
#   * the app shell, the wallet menu, the sign in notice and Settings are
#     translated; any message not translated yet shows in English
#   * Arabic reads right to left: the shell mirrors, the player and the
#     timeline stay left to right, Noto Sans Arabic sets the Arabic letters
#   * OFF BY DEFAULT. Languages only switch on with NEXT_PUBLIC_LANGUAGES=on.
#     Without it the site is English for everyone, reads no cookie, shows
#     no picker and keeps every page static, so production is unchanged
#     until 15b and 15c translate the rest and the Privacy Policy changes.
#
#   BACKEND    3 changed. Migration 023_language
#   FRONTEND   9 new files, 14 changed. Package next-intl 4.14.9
#
#   ./vm_lang.sh            apply (needs Part 14f on the branch)
#   ./vm_lang.sh --force    apply even if local files differ from GitHub
#   ./vm_lang.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_lang"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_lang_backups"

ADD=(
  "frontend/src/i18n/config.ts"
  "frontend/src/i18n/request.ts"
  "frontend/src/i18n/global.d.ts"
  "frontend/src/components/layout/LanguagePicker.tsx"
  "frontend/src/messages/en.json"
  "frontend/src/messages/es.json"
  "frontend/src/messages/fr.json"
  "frontend/src/messages/ar.json"
  "frontend/src/messages/pt.json"
)
