fQo=
B64_A8
verify "$TMPD/a8" "${NEW_ADD[8]}" "frontend/src/messages/pt.json"

grep -q 'vm_lang' "$TMPD/a0" || die "config.ts payload missing marker. Aborting."
grep -q 'export function negotiate' "$TMPD/a0" || die "config.ts payload is wrong. Aborting."
grep -q 'getRequestConfig' "$TMPD/a1" || die "request.ts payload is wrong. Aborting."
grep -q 'interface AppConfig' "$TMPD/a2" || die "global.d.ts payload is wrong. Aborting."
grep -q 'export function LanguageSync' "$TMPD/a3" || die "LanguagePicker.tsx payload is wrong. Aborting."
grep -q '"storageUsed"' "$TMPD/a4" || die "en.json payload is wrong. Aborting."
grep -q 'سياسة الخصوصية' "$TMPD/a7" || die "frontend/src/messages/ar.json payload is wrong. Aborting."
grep -q 'العربية' "$TMPD/a0" || die "frontend/src/i18n/config.ts payload is wrong. Aborting."
grep -q -- '023_language' "$TMPD/m0" || die "migrations.ts payload is wrong. Aborting."
grep -q -- '022_costs' "$TMPD/m0" || die "migrations.ts payload lost 14e. Aborting."
grep -q -- 'bad_language' "$TMPD/m1" || die "account.ts payload is wrong. Aborting."
grep -q -- 'deleteAccountData' "$TMPD/m1" || die "account.ts payload lost 13a. Aborting."
grep -q -- '"next-intl": "4.14.9"' "$TMPD/m3" || die "package.json payload is wrong. Aborting."
grep -q -- 'node_modules/next-intl' "$TMPD/m4" || die "package-lock.json payload is wrong. Aborting."
grep -q -- 'createNextIntlPlugin' "$TMPD/m5" || die "next.config.mjs payload is wrong. Aborting."
grep -q -- '--font-stack' "$TMPD/m7" || die "globals.css payload is wrong. Aborting."
grep -q -- 'NextIntlClientProvider' "$TMPD/m8" || die "layout.tsx payload is wrong. Aborting."
grep -q -- 'LanguagePicker' "$TMPD/m9" || die "settings page payload is wrong. Aborting."
grep -q -- 'Delete my data' "$TMPD/m9" || die "frontend/src/app/settings/page.tsx payload is wrong. Aborting."
grep -q -- 'LanguagePicker' "$TMPD/m11" || die "AppShell.tsx payload is wrong. Aborting."
grep -q -- 'SHOW_PLANNED' "$TMPD/m11" || die "AppShell.tsx payload lost the shell. Aborting."
grep -q -- 't.rich("consent"' "$TMPD/m14" || die "WalletButton.tsx payload is wrong. Aborting."
grep -q -- 'dir="ltr"' "$TMPD/m15" || die "VideoPlayer.tsx payload is wrong. Aborting."
grep -q -- 'language: Locale | null' "$TMPD/m16" || die "api.ts payload is wrong. Aborting."
say "26 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied the language layer (Part 15a)."
say "Migration 023_language runs by itself when the backend starts."
say "Install the new package and verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build)"
say "  (cd frontend && npm install && npx tsc --noEmit && npm run build)"
say "  (cd dashboard && npx tsc --noEmit)"
say "To see the languages on the preview only: Vercel, the project, Settings,"
say "Environment Variables, NEXT_PUBLIC_LANGUAGES = on, environment Preview only."
say "Leave it unset for Production until Part 15c."
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_lang.sh --revert"
